export const encoder = new TextEncoder();
export const MAX_BYTES = 65536;
export function toBase64(bytes) { let s=''; for(const b of bytes)s+=String.fromCharCode(b); return btoa(s); }
export function fromBase64(s) { if(typeof s!=='string'||s.length>120000||! /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(s)) throw new Error('Invalid ciphertext package.'); return Uint8Array.from(atob(s),c=>c.charCodeAt(0)); }
export async function derive(passphrase,nonce){ const key=await crypto.subtle.importKey('raw',encoder.encode(passphrase),'PBKDF2',false,['deriveBits']); return new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:nonce,iterations:100000,hash:'SHA-256'},key,512)); }
export function stream(key,length){let integer=0;for(let i=0;i<6;i++)integer=integer*256+key[i];const seed=.05+.9*integer/281474976710656;let x=seed;const step=()=>{x=3.99*x*(1-x);return x;};for(let i=0;i<1000;i++)step();const bytes=new Uint8Array(length);const trajectory=[];for(let i=0;i<Math.max(length,160);i++){step();step();if(i<160)trajectory.push(x);if(i<length)bytes[i]=((Math.floor(x*4294967296)>>>0)&255)^key[i%32];}return {bytes,seed,trajectory};}
export function transform(input,keyBytes,nonce,decrypt=false){let previous=nonce[0];const out=new Uint8Array(input.length);for(let i=0;i<input.length;i++){out[i]=input[i]^keyBytes[i]^previous;previous=decrypt?input[i]:out[i];}return out;}
function authenticatedData(nonce,data){const bytes=new Uint8Array(1+nonce.length+data.length);bytes[0]=1;bytes.set(nonce,1);bytes.set(data,17);return bytes;}
async function authKey(key){return crypto.subtle.importKey('raw',key.slice(32),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);}
export async function encryptMessage(message,passphrase){const plain=encoder.encode(message);if(!plain.length)throw new Error('Enter a message to encrypt.');if(plain.length>MAX_BYTES)throw new Error('Keep your message within 65,536 UTF-8 bytes.');if(!passphrase.trim())throw new Error('Enter a secret passphrase.');const start=performance.now();const nonce=crypto.getRandomValues(new Uint8Array(16));const key=await derive(passphrase,nonce);const generated=stream(key,plain.length);const cipher=transform(plain,generated.bytes,nonce);const tag=new Uint8Array(await crypto.subtle.sign('HMAC',await authKey(key),authenticatedData(nonce,cipher)));const elapsed=performance.now()-start;const changed=key.slice();changed[0]^=1;const other=transform(plain,stream(changed,plain.length).bytes,nonce);let changedBits=0;for(let i=0;i<cipher.length;i++){let b=cipher[i]^other[i];while(b){changedBits+=b&1;b>>>=1;}}const packet={v:1,nonce:toBase64(nonce),data:toBase64(cipher),tag:toBase64(tag)};const packaged=toBase64(encoder.encode(JSON.stringify(packet)));return {packet,packaged,plain,cipher,keyBytes:generated.bytes,nonce,...generated,elapsed,sensitivity:changedBits/(plain.length*8)*100};}
export async function decryptMessage(packaged,passphrase){if(!passphrase.trim())throw new Error('Enter the passphrase used for encryption.');let packet,nonce,data,tag;try{if(typeof packaged!=='string'||packaged.length>160000)throw 0;packet=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(fromBase64(packaged.trim())));if(packet.v!==1)throw 0;nonce=fromBase64(packet.nonce);data=fromBase64(packet.data);tag=fromBase64(packet.tag);if(nonce.length!==16||tag.length!==32||!data.length||data.length>MAX_BYTES)throw 0;}catch{throw new Error('Invalid ciphertext package. Paste the full packaged Base64 output.');}const key=await derive(passphrase,nonce);const valid=await crypto.subtle.verify('HMAC',await authKey(key),tag,authenticatedData(nonce,data));if(!valid)throw new Error('Authentication failed. The passphrase is incorrect or the ciphertext was modified.');return new TextDecoder('utf-8',{fatal:true}).decode(transform(data,stream(key,data.length).bytes,nonce,true));}
export function stats(bytes){const counts=new Array(256).fill(0);let ones=0;for(let b of bytes){counts[b]++;while(b){ones+=b&1;b>>>=1;}}let entropy=0;for(const c of counts){if(c){const p=c/bytes.length;entropy-=p*Math.log2(p);}}return {counts,entropy,unique:counts.filter(Boolean).length,ones:bytes.length?ones/(bytes.length*8)*100:0};}
